package clientgen

import (
	"fmt"
	"go/token"
	"strings"

	"github.com/joakimcarlsson/minmux/openapi"
)

// Config controls a single generation run.
type Config struct {
	// Spec is the document to generate from, typically
	// openapi.Generator.Spec(router). Required.
	Spec *openapi.Document

	// Package is the package name of the generated client. Required.
	Package string

	// Out is the directory the generated files are written to. It is
	// created if missing. Required by Generate; ignored by Render.
	Out string

	// ClientName overrides the name of the generated client type.
	// Defaults to "Client".
	ClientName string

	// Command is recorded in the "Code generated by" header of every
	// file. Defaults to "clientgen". Set it to the go:generate line that
	// produced the output so a reader knows how to regenerate it.
	//
	// It must not carry anything that varies between runs — a timestamp
	// or an absolute path would make regeneration produce a spurious
	// diff and defeat a CI drift check.
	Command string
}

// generatedFileNames lists every file a run emits, in emission order.
// Generate prunes stale *.gen.go files not in this set so that removing
// the last streaming operation does not leave an orphaned file behind.
var generatedFileNames = []string{
	"client.gen.go",
	"types.gen.go",
	"operations.gen.go",
}

func (c *Config) normalize() error {
	if c.Spec == nil {
		return fmt.Errorf("clientgen: Config.Spec is required")
	}
	if c.Package == "" {
		return fmt.Errorf("clientgen: Config.Package is required")
	}
	if !token.IsIdentifier(c.Package) || token.Lookup(c.Package).IsKeyword() {
		return fmt.Errorf(
			"clientgen: Config.Package %q is not a valid Go package name",
			c.Package,
		)
	}
	if c.ClientName == "" {
		c.ClientName = "Client"
	}
	if !token.IsIdentifier(c.ClientName) {
		return fmt.Errorf(
			"clientgen: Config.ClientName %q is not a valid Go identifier",
			c.ClientName,
		)
	}
	if c.Command == "" {
		c.Command = "clientgen"
	}
	if strings.ContainsAny(c.Command, "\n\r") {
		return fmt.Errorf("clientgen: Config.Command must be a single line")
	}
	return nil
}

// File is one generated source file.
type File struct {
	Name    string
	Content []byte
}
